# ---- auto fill H by valence ----
val = Counter()
for i,j,o in bonds:
    val[i]+=o; val[j]+=o
target = {'C':4,'N':3,'P':3}
extra=[]
for i,(s,c) in enumerate(atoms):
    if s in target:
        need = target[s]-val[i]
        for _ in range(need):
            # place H away from existing neighbors
            nbrs=[atoms[j][1] for j in range(len(atoms)) if any((i==a and j==b) or (i==b and j==a) for a,b,_ in bonds)]
            dirs=[]
            for j,(i2,j2,o) in enumerate(bonds):
                if i2==i: nbrs.append(atoms[j2][1])
                if j2==i: nbrs.append(atoms[i2][1])
            d = c - (sum(nbrs)/len(nbrs) if nbrs else c+np.array([1,0,0]))
            if np.linalg.norm(d)<1e-6: d=np.array([1,0,0])
            d = unit(d)
            # add small perpendicular jitter for multiple H
            if len(extra_h_for := [e for e in extra if e[0]==i])>0:
                perp = unit(np.cross(d,[0,0,1])) if abs(d[2])<0.9 else unit(np.cross(d,[1,0,0]))
                ang = 2*math.pi*len(extra_h_for)/3
                d = unit(d*math.cos(0.5)+ (perp*math.cos(ang)+unit(np.cross(d,perp))*math.sin(ang))*math.sin(0.6))
            extra.append((i, add('H', *(c + 1.09*d))))
for parent,h in extra:
    bonds.append((parent,h,1))
with open('build/model_raw.xyz','w') as f:
    f.write(f'{len(atoms)}\nmodel raw\n')
    for s,c in atoms:
        f.write(f'{s} {c[0]:.4f} {c[1]:.4f} {c[2]:.4f}\n')
with open('build/bonds.txt','w') as f:
    for i,j,o in bonds:
        f.write(f'{i} {j} {o}\n')
print('FINAL atoms', len(atoms), 'bonds', len(bonds))
print(Counter(s for s,_ in atoms))
