import numpy as np
L=open('build/model_ff.xyz').read().split('\n')
n=int(L[0]); ats=[];X=[]
for line in L[2:2+n]:
    t=line.split(); ats.append(t[0]); X.append([float(v) for v in t[1:4]])
X=np.array(X)
def d(i,j): return np.linalg.norm(X[i]-X[j])
def ang(a,c,b):
    v1=X[a]-X[c]; v2=X[b]-X[c]
